/**
 * Known costs in USD; calls without a price or reported usage are counted in unknownCostCalls, never as zero
 */
export type AiCostSummary = {
    cost: number;
    externalCost: number;
    calls: number;
    unknownCostCalls: number;
    inputTokens: number;
    outputTokens: number;
    cacheReadTokens: number;
    imageCount: number;
    audioSeconds: number;
    activePeople: number;
};

/**
 * One UTC day of one series: a data boundary (INTERNAL, EXTERNAL, NONE), a model name or ALL
 */
export type AiCostDay = {
    day: string;
    series: string;
    cost: number;
    calls: number;
    inputTokens: number;
    outputTokens: number;
    cacheReadTokens: number;
};

export type AiCostDetail = {
    summary: AiCostSummary;
    daily: Array<AiCostDay>;
    models: Array<AiCostRow>;
    flows: Array<AiCostRow>;
    providers: Array<AiCostRow>;
};

/**
 * A ranked row: a person (key SYSTEM for work without a person), Group, model, task or provider
 */
export type AiCostRow = {
    key: string;
    label: string;
    detail: string | null;
    calls: number;
    unknownCostCalls: number;
    inputTokens: number;
    outputTokens: number;
    cost: number;
};

export type ApiProblem = {
    /**
     * Stable problem type for capability failures; omitted means RFC 9457 `about:blank`.
     */
    type?: string;
    /**
     * Short human-readable problem category.
     */
    title: string;
    /**
     * HTTP status code.
     */
    status: number;
    /**
     * Safe human-readable fallback detail.
     */
    detail: string;
    /**
     * Request path that produced the problem.
     */
    instance: string;
    /**
     * Stable capability-prefixed code; present only for expected capability failures.
     */
    code?: string;
    /**
     * Field validation failures with safe allowlisted parameters; no rejected values.
     */
    errors?: Array<{
        field: string;
        /**
         * Compatible fallback message; clients localize by code.
         */
        message: string;
        code: 'REQUIRED' | 'INVALID' | 'EMAIL' | 'SIZE' | 'MIN' | 'MAX';
        params: {
            min?: number;
            max?: number;
        };
    }>;
};

